ht:1.45}.mode-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.mode-card{position:relative;display:block;cursor:pointer}.mode-card input{position:absolute;opacity:0;pointer-events:none}.mode-card-body{display:block;min-height:105px;padding:16px;border:1px solid rgba(255,255,255,.09);border-radius:14px;background:rgba(7,11,25,.45);transition:.16s ease}.mode-card-body strong{display:block;margin-bottom:5px;color:#e8e9f3}.mode-card-body span{display:block;color:#858aa2;font-size:12px;line-height:1.45}.mode-card input:checked+.mode-card-body{border-color:#7655ef;background:linear-gradient(145deg,rgba(103,69,224,.19),rgba(20,25,48,.88));box-shadow:inset 0 0 0 1px rgba(127,91,246,.22)}.mode-card input:checked+.mode-card-body strong{color:#fff}.sale-box{display:grid;gap:15px;margin-top:16px;padding:17px;border:1px solid rgba(124,89,243,.22);border-radius:15px;background:rgba(91,62,183,.06)}.sale-box[hidden]{display:none}.sale-preview{display:flex;justify-content:space-between;gap:12px;padding:11px 13px;border-radius:11px;background:rgba(3,7,18,.48);font-size:12px}.sale-preview span{color:#8f94aa}.sale-preview strong{text-align:right}.send-action{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:18px 24px;background:rgba(7,10,22,.62)}.send-action p{margin:0;color:#8d92a8;font-size:12px;max-width:560px}.send-action .btn{min-width:250px;min-height:48px}.send-alerts{display:grid;gap:8px}.send-alerts .flash{margin:0}.required{color:#8c6cff}.no-events{padding:22px;border:1px solid rgba(227,170,76,.2);border-radius:14px;background:rgba(114,74,14,.09);color:#d7b77c}.no-events strong{display:block;color:#f0d29b;margin-bottom:5px}@media(max-width:760px){.send-hero{padding:23px 20px}.send-hero-top{flex-direction:column}.send-hero-top .btn{width:100%;text-align:center}.send-steps{grid-template-columns:repeat(2,1fr)}.send-section{grid-template-columns:1fr;padding:20px}.send-grid,.mode-grid{grid-template-columns:1fr}.send-field.full{grid-column:auto}.send-action{align-items:stretch;flex-direction:column}.send-action .btn{width:100%;min-width:0}}@media(max-width:430px){.send-steps{grid-template-columns:1fr}.send-step:nth-child(n+3){display:none}}
</style>
